from collections import Counter, deque
from pathlib import Path

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(cells)>=4:
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                boxes.append((color,min(rs),max(rs),min(cs),max(cs)))
    main={b[0] for b in boxes}
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col==bg or col in main: continue
            matches=[b for b in boxes if b[1]<=r<=b[2] and b[3]<=c<=b[4]]
            out[r][c]=matches[0][0] if matches else bg
    return out

